import{_ as l,o,c as s,a5 as e}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"css处理","description":"浏览器在下载和处理 CSS 文件时，不会停止 HTML 的解析过程，但会停止 HTML 的渲染过程。这里详细解释一下这个过程： 浏览器下载 CSS 文件时的行为 1. 开始解析 HTML ： 浏览器从上到下解析 HTML 文件，遇到 \\\\<link\\\\ 标签时，会发现外部 CSS 文。","frontmatter":{"title":"css处理","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","前端知识复习"],"description":"浏览器在下载和处理 CSS 文件时，不会停止 HTML 的解析过程，但会停止 HTML 的渲染过程。这里详细解释一下这个过程： 浏览器下载 CSS 文件时的行为 1. 开始解析 HTML ： 浏览器从上到下解析 HTML 文件，遇到 \\\\<link\\\\ 标签时，会发现外部 CSS 文。","sidebarWeight":13,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/复习大纲/浏览器/css处理.md"},"headers":[],"relativePath":"posts/前端面试与实战/01-前端知识复习/浏览器/css处理.md","filePath":"posts/前端面试与实战/01-前端知识复习/浏览器/css处理.md"}'),i={name:"posts/前端面试与实战/01-前端知识复习/浏览器/css处理.md"};function r(a,t,S,c,n,d){return o(),s("div",null,[...t[0]||(t[0]=[e('<div><h1 id="css处理" tabindex="-1">css处理 <a class="header-anchor" href="#css处理" aria-label="Permalink to &quot;css处理&quot;">​</a></h1><blockquote><p>本节目标：理解“css处理”的核心思路，并能把它用于实际开发或面试表达。 浏览器在下载和处理 CSS 文件时，不会停止 HTML 的解析过程，但会停止 HTML 的渲染过程。这里详细解释一下这个过程：</p></blockquote><h3 id="浏览器下载-css-文件时的行为" tabindex="-1">浏览器下载 CSS 文件时的行为 <a class="header-anchor" href="#浏览器下载-css-文件时的行为" aria-label="Permalink to &quot;浏览器下载 CSS 文件时的行为&quot;">​</a></h3><ol><li><strong>开始解析 HTML</strong>：</li></ol><ul><li>浏览器从上到下解析 HTML 文件，遇到 <code>\\&lt;link\\&gt;</code> 标签时，会发现外部 CSS 文件。</li></ul><ol start="2"><li><strong>下载 CSS 文件</strong>：</li></ol><ul><li>浏览器开始异步下载 CSS 文件，不会阻塞 HTML 的解析过程。</li></ul><ol start="3"><li><strong>继续解析 HTML</strong>：</li></ol><ul><li>浏览器继续解析 HTML 文件，构建 DOM 树。</li></ul><ol start="4"><li><strong>等待 CSSOM 完成</strong>：</li></ol><ul><li>尽管 HTML 的解析没有被阻塞，但浏览器在构建 CSSOM 树（CSS 对象模型）时，渲染进程会等待 CSS 文件下载和解析完成。浏览器需要确保 CSSOM 树和 DOM 树都构建完成后，才能进行下一步的布局和绘制。这是因为 CSS 样式可能会影响页面的布局。</li></ul><p>详细示例流程 以下是一个详细的示例流程，展示浏览器如何处理 CSS 文件的下载和 HTML 解析：</p><ol><li><p>HTML 文件示例 &lt;!DOCTYPE html&gt; &lt;html&gt; &lt;head&gt; &lt;title&gt;Example&lt;/title&gt; &lt;link rel=&quot;stylesheet&quot; type=&quot;text/css&quot; href=&quot;styles.css&quot;&gt; &lt;/head&gt; &lt;body&gt; &lt;h1&gt;Hello, World!&lt;/h1&gt; &lt;p&gt;This is a paragraph.&lt;/p&gt; &lt;/body&gt; &lt;/html&gt;</p></li><li><p>解析过程</p></li><li><p><strong>解析 HTML</strong>：</p></li></ol><ul><li>浏览器开始解析 HTML 文件，遇到 <code>\\&lt;link\\&gt;</code> 标签时，发现需要下载 <code>styles.css</code> 文件。</li></ul><ol start="2"><li><strong>下载 CSS 文件</strong>：</li></ol><ul><li>浏览器异步下载 <code>styles.css</code> 文件。</li></ul><ol start="3"><li><strong>继续解析 HTML</strong>：</li></ol><ul><li>浏览器继续解析 HTML 文件，构建 DOM 树。</li></ul><ol start="4"><li><strong>等待 CSSOM 完成</strong>：</li></ol><ul><li>浏览器等待 CSS 文件下载完成并解析成 CSSOM 树。此时浏览器会暂停渲染，但继续解析 HTML 文件。</li></ul><ol start="5"><li><strong>构建 CSSOM 树</strong>：</li></ol><ul><li>CSS 文件下载并解析完成后，浏览器构建 CSSOM 树。</li></ul><ol start="6"><li><strong>合并 DOM 和 CSSOM</strong>：</li></ol><ul><li>浏览器将 DOM 树和 CSSOM 树结合，生成渲染树。</li></ul><ol start="7"><li><strong>布局和绘制</strong>：</li></ol><ul><li>浏览器进行布局（计算每个元素的位置和大小）并绘制（将元素绘制到屏幕上）。</li></ul><p>影响页面渲染的因素</p><ul><li><strong>CSS 文件的下载和解析</strong>：CSS 文件的下载和解析会影响页面的首次渲染时间，因为浏览器需要等待 CSSOM 树完成构建。</li><li><strong>JavaScript 的执行</strong>：如果 HTML 文件中包含 JavaScript，并且在 <code>\\&lt;head\\&gt;</code> 部分引入的 JavaScript 没有使用 <code>async</code> 或 <code>defer</code> 属性，浏览器会暂停 HTML 的解析，直到 JavaScript 执行完成。这会影响页面的渲染时间。<a href="./async和defer">async、defer、DomContentLoaded、onLoad</a></li></ul><p>性能优化建议</p><ol><li><strong>将 CSS 放在 <code>\\&lt;head\\&gt;</code></strong>：确保 CSS 文件在 HTML 文件的 <code>\\&lt;head\\&gt;</code> 部分引用，这样可以尽早开始下载和解析 CSS 文件。</li><li><strong>减少 CSS 文件的大小</strong>：尽量精简 CSS 文件，减少不必要的样式定义。</li><li><strong>使用异步加载 JavaScript</strong>：在引入 JavaScript 文件时，使用 <code>async</code> 或 <code>defer</code> 属性，确保 JavaScript 文件不会阻塞 HTML 的解析。 &lt;script src=&quot;script.js&quot; async&gt;&lt;/script&gt; &lt;!-- 或者 --&gt; &lt;script src=&quot;script.js&quot; defer&gt;&lt;/script&gt;</li></ol></div>',1)])])}const u=l(i,[["render",r]]);export{p as __pageData,u as default};
